{"content": """"List every span candidate used by build.py and check it resolves verbatim."""
import re, sys
PAP = "/home/user/gp-rarelink/data/literature/ssadh/fulltext_md/9093300.md"
txt = open(PAP, encoding="utf-8").read()
lines = txt.split("\n")

kept, idx, prev = [], [], False
for i, ch in enumerate(txt):
    if ch == "\u00ad":
        continue
    sp = ch in " \t\n\r"
    if sp and prev:
        continue
    kept.append(" " if sp else ch); idx.append(i); prev = sp
key = "".join(kept)

def Q(spec):
    a, b = spec if isinstance(spec, tuple) else (spec, spec)
    na = re.sub(r"\s+", " ", a).strip(); nb = re.sub(r"\s+", " ", b).strip()
    i = key.find(na)
    if i < 0:
        return ("MISS", spec)
    j = key.find(nb, i)
    if j < 0:
        return ("ENDMISS", spec)
    return ("ok", txt[idx[i]:idx[j+len(nb)-1]+1])

